    if (!(cin >> n >> m)) return 0;

    vector<long long> a(n), b(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> b[i];

    const long long INF = (1LL << 60);
    int maxBal = n; // balance never exceeds n within one block

    // dp[pos][bal] = minimal cost to reach position pos with balance bal
    vector<vector<long long>> dp(n + 1, vector<long long>(maxBal + 1, INF));
    dp[0][0] = 0;

    for (int pos = 0; pos < n; ++pos) {
        for (int bal = 0; bal <= maxBal; ++bal) {
            long long cur = dp[pos][bal];
            if (cur == INF) continue;

            // open bracket
            if (bal + 1 <= maxBal) {
                long long &ref = dp[pos + 1][bal + 1];
                long long cost = cur + a[pos];
                if (cost < ref) ref = cost;
            }

            // close bracket
            if (bal > 0) {
                long long &ref = dp[pos + 1][bal - 1];
                long long cost = cur + b[pos];
                if (cost < ref) ref = cost;
            }
        }
    }

    // Build transition matrix T of size (n+1) x (n+1)
    int sz = n + 1;
    vector<vector<long long>> T(sz, vector<long long>(sz, INF));

    for (int bal = 0; bal <= n; ++bal) {
        for (int newBal = 0; newBal <= n; ++newBal) {
            long long best = INF;
            for (int pos = 0; pos < n; ++pos) {
                int delta = newBal - bal;
                if (delta == 1) { // open
                    if (bal + 1 <= n) {
                        long long cost = a[pos];
                        if (cost < best) best = cost;
                    }
                } else if (delta == -1) { // close
                    if (bal > 0) {
                        long long cost = b[pos];
                        if (cost < best) best = cost;
                    }
                }
            }
            if (best < INF) T[bal][newBal] = best;
        }
    }

    // We actually need exact per-position costs, not just minimal per transition.
    // So we must use DP over positions within each block, not a simple matrix over balances.
    // Instead, we treat each block as length n with periodic costs and use DP over nm positions.
    // But nm can be up to 2e8, so we need to exploit periodicity via DP over one period and then
    // use min-plus matrix exponentiation over balances.

    // Rebuild correct transition matrix using DP over one block:
    // For each starting balance s, compute minimal cost to reach each ending balance e after n steps.
    for (int s = 0; s <= n; ++s) {
        vector<long long> cur(maxBal + 1, INF), nxt(maxBal + 1, INF);
        cur[s] = 0;
        for (int pos = 0; pos < n; ++pos) {
            fill(nxt.begin(), nxt.end(), INF);
            for (int bal = 0; bal <= maxBal; ++bal) {
                long long val = cur[bal];
                if (val == INF) continue;
                // open
                if (bal + 1 <= maxBal) {
                    long long &ref = nxt[bal + 1];
                    long long cost = val + a[pos];
                    if (cost < ref) ref = cost;
                }
                // close
                if (bal > 0) {
                    long long &ref = nxt[bal - 1];
                    long long cost = val + b[pos];
                    if (cost < ref) ref = cost;
                }
            }
            cur.swap(nxt);
        }
        for (int e = 0; e <= n; ++e) {
            T[s][e] = cur[e];
        }
    }

    // Min-plus matrix multiplication
    auto matMul = [&](const vector<vector<long long>> &A,
                      const vector<vector<long long>> &B) {
        vector<vector<long long>> C(sz, vector<long long>(sz, INF));
        for (int i = 0; i < sz; ++i) {
            for (int k = 0; k < sz; ++k) {
                if (A[i][k] == INF) continue;
                long long aik = A[i][k];
                for (int j = 0; j < sz; ++j) {
                    if (B[k][j] == INF) continue;
                    long long val = aik + B[k][j];
                    if (val < C[i][j]) C[i][j] = val;
                }
            }
        }
        return C;
    };

    // Exponentiate T to power m/n blocks
    long long blocks = m / n;
    vector<vector<long long>> R(sz, vector<long long>(sz, INF));
    for (int i = 0; i < sz; ++i) R[i][i] = 0;

    vector<vector<long long>> P = T;
    while (blocks > 0) {
        if (blocks & 1) R = matMul(R, P);
        P = matMul(P, P);
        blocks >>= 1;
    }

    // Initial vector: balance 0 with cost 0
    vector<long long> dp0(sz, INF), dp1(sz, INF);
    dp0[0] = 0;
    for (int i = 0; i < sz; ++i) {
        if (dp0[i] == INF) continue;
        for (int j = 0; j < sz; ++j) {
            if (R[i][j] == INF) continue;
            long long val = dp0[i] + R[i][j];
            if (val < dp1[j]) dp1[j] = val;
        }
    }

    cout << dp1[0] << '\n';
    return 0;
}

