            g[bal] = INF;

        for (int bal = 0; bal <= maxBal; ++bal) {
            if (f[bal] == INF) continue;
            for (int d = 0; d <= maxBal; ++d) {
                if (transCost[d] == INF) continue;
                int nb = bal + d;
                if (nb > maxBal) continue;
                long long cost = f[bal] + transCost[d];
                if (cost < g[nb]) g[nb] = cost;
            }
        }
        for (int bal = 0; bal <= maxBal; ++bal)
            f[bal] = g[bal];
    }

    cout << f[0] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    if (!(cin >> n >> m)) return 0;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> b[i];

    int maxBal = n;
    const long long INF = (1LL << 60);
    // dp[pos][balance] for one block of length n
    static long long dp[21][21], ndp[21][21];
    for (int bal = 0; bal <= maxBal; ++bal)
        dp[0][bal] = (bal == 0 ? 0 : INF);

    for (int pos = 0; pos < n; ++pos) {
        int idx = pos % n;
        for (int bal = 0; bal <= maxBal; ++bal) ndp[pos+1][bal] = INF;
        for (int bal = 0; bal <= maxBal; ++bal) {
            long long cur = dp[pos][bal];
            if (cur == INF) continue;
            // open
            if (bal + 1 <= maxBal) {
                ndp[pos+1][bal+1] = min(ndp[pos+1][bal+1], cur + a[idx]);
            }
            // close
            if (bal > 0) {
                ndp[pos+1][bal-1] = min(ndp[pos+1][bal-1], cur + b[idx]);
            }
        }
        for (int bal = 0; bal <= maxBal; ++bal)
            dp[pos+1][bal] = ndp[pos+1][bal];
    }

    // transition matrix for balances 0..n
    int states = n + 1;
    vector<vector<long long>> T(states, vector<long long>(states, INF));
    for (int s = 0; s <= n; ++s) {
        for (int t = 0; t <= n; ++t) {
            T[s][t] = dp[n][t];
        }
    }

    auto multiply = [&](const vector<vector<long long>> &A,
                        const vector<vector<long long>> &B) {
        vector<vector<long long>> C(states, vector<long long>(states, INF));
        for (int i = 0; i < states; ++i) {
            for (int k = 0; k < states; ++k) {
                if (A[i][k] == INF) continue;
                long long aik = A[i][k];
                for (int j = 0; j < states; ++j) {
                    if (B[k][j] == INF) continue;
                    long long val = aik + B[k][j];
                    if (val < C[i][j]) C[i][j] = val;
                }
            }
        }
        return C;
    };

    long long blocks = m / n;
    vector<vector<long long>> R(states, vector<long long>(states, INF));
    for (int i = 0; i < states; ++i) R[i][i] = 0;
    vector<vector<long long>> P = T;

    while (blocks) {
        if (blocks & 1) R = multiply(R, P);
        P = multiply(P, P);
        blocks >>= 1;
    }

    long long ans = R[0][0];
    cout << ans << '\n';
    return 0;
}
